/**
 * @summary Get background job status (bulk operations)
 */
export const getGetJobStatusUrl = (projectId: number, jobId: string) => {
  return `/api/projects/${projectId}/jobs/${jobId}`;
};

export const getJobStatus = async (
  projectId: number,
  jobId: string,
  options?: RequestInit,
): Promise<JobStatus> => {
  return customFetch<JobStatus>(getGetJobStatusUrl(projectId, jobId), {
    ...options,
    method: "GET",
  });
};

export const getGetJobStatusQueryKey = (projectId: number, jobId: string) => {
  return [`/api/projects/${projectId}/jobs/${jobId}`] as const;
};

export const getGetJobStatusQueryOptions = <
  TData = Awaited<ReturnType<typeof getJobStatus>>,
  TError = ErrorType<unknown>,
>(
  projectId: number,
  jobId: string,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getJobStatus>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getGetJobStatusQueryKey(projectId, jobId);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getJobStatus>>> = ({
    signal,
  }) => getJobStatus(projectId, jobId, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!(projectId && jobId),
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof getJobStatus>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetJobStatusQueryResult = NonNullable<
  Awaited<ReturnType<typeof getJobStatus>>
>;
export type GetJobStatusQueryError = ErrorType<unknown>;

/**
 * @summary Get background job status (bulk operations)
 */

export function useGetJobStatus<
  TData = Awaited<ReturnType<typeof getJobStatus>>,
  TError = ErrorType<unknown>,
>(
  projectId: number,
  jobId: string,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getJobStatus>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetJobStatusQueryOptions(projectId, jobId, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
